-- Create Database
CREATE DATABASE IF NOT EXISTS `sotopo` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `sotopo`;

-- 1. News Table with full content details from Stitch
CREATE TABLE IF NOT EXISTS `news` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `tag` VARCHAR(255) NOT NULL,
  `date` VARCHAR(255) NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `summary` TEXT NOT NULL,
  `content` LONGTEXT NOT NULL,
  `image_url` TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Committees Table
CREATE TABLE IF NOT EXISTS `committees` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `role` VARCHAR(255) NOT NULL,
  `description` TEXT NOT NULL,
  `image_url` TEXT NOT NULL,
  `level` INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Announcements Table
CREATE TABLE IF NOT EXISTS `announcements` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `announcement_number` VARCHAR(255) NOT NULL,
  `topic` VARCHAR(255) NOT NULL,
  `approve_date` VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3.1. Approved Monks Table
CREATE TABLE IF NOT EXISTS `approved_monks` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `announcement_id` INT NOT NULL,
  `monk_name` VARCHAR(255) NOT NULL,
  `temple` VARCHAR(255) NOT NULL,
  `destination` VARCHAR(255) NOT NULL,
  `approve_date` VARCHAR(255) NOT NULL,
  FOREIGN KEY (`announcement_id`) REFERENCES `announcements`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 4. Offices Table
CREATE TABLE IF NOT EXISTS `offices` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `address` TEXT NOT NULL,
  `phone` VARCHAR(255) NOT NULL,
  `hours` VARCHAR(255) NOT NULL,
  `type` VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 5. Applications Table
CREATE TABLE IF NOT EXISTS `applications` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `tracking_number` VARCHAR(255) NOT NULL UNIQUE,
  `monk_name` VARCHAR(255) NOT NULL,
  `temple` VARCHAR(255) NOT NULL,
  `destination` VARCHAR(255) NOT NULL,
  `status` VARCHAR(255) NOT NULL,
  `step` INT NOT NULL,
  `updated_at` VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- Seeding Data (ระบบบริหารการไปต่างประเทศ ศ.ต.ภ.)
-- --------------------------------------------------------

TRUNCATE TABLE `approved_monks`;
DELETE FROM `announcements`;
TRUNCATE TABLE `news`;
TRUNCATE TABLE `committees`;
TRUNCATE TABLE `offices`;
TRUNCATE TABLE `applications`;

-- Seeding news with full detailed contents
INSERT INTO `news` (`id`, `tag`, `date`, `title`, `summary`, `content`, `image_url`) VALUES
(1, 'ข่าวสาร', '๑๒ กรกฎาคม ๒๕๖๙', 'การประชุมคณะกรรมการ ศ.ต.ภ. ครั้งที่ ๕/๒๕๖๙ พิจารณาคำขอเดินทางไปต่างประเทศ', 'สรุปผลการพิจารณาคำขอเดินทางไปปฏิบัติศาสนกิจในต่างประเทศประจำเดือนกรกฎาคม ๒๕๖๙ อนุมัติพระธรรมทูตจำนวน ๔๕ รูป', '<p>เมื่อวันที่ ๑๒ กรกฎาคม ๒๕๖๙ คณะกรรมการศูนย์ควบคุมการไปต่างประเทศของพระภิกษุสามเณร (ศ.ต.ภ.) ได้จัดประชุมครั้งที่ ๕/๒๕๖๙ ณ อาคารมหาจุฬาลงกรณราชวิทยาลัย โดยมี <strong>พระพรหมบัณฑิต (ประยูร ธมฺมจิตฺโต)</strong> ประธานคณะกรรมการ ศ.ต.ภ. เป็นประธานในการประชุม</p><h4>มติและผลการพิจารณา:</h4><ul><li>ที่ประชุมมีมติเห็นชอบอนุมัติการขอเดินทางไปปฏิบัติศาสนกิจในต่างประเทศของพระภิกษุสามเณร ประจำงวดเดือนกรกฎาคม ๒๕๖๙ รวมทั้งสิ้น <strong>๔๕ รูป</strong></li><li>สายสหรัฐอเมริกา จำนวน ๑๒ รูป</li><li>สายสหราชอาณาจักรและทวีปยุโรป จำนวน ๑๕ รูป</li><li>สายประเทศอินเดียและเนปาล จำนวน ๑๐ รูป</li><li>สายเอเชียตะวันออกและออสเตรเลีย จำนวน ๘ รูป</li></ul><p>ประธานคณะกรรมการได้เน้นย้ำให้พระภิกษุทุกรูปที่ได้รับอนุมัติ ปฏิบัติตนตามระเบียบมหาเถรสมาคมอย่างเคร่งครัด รักษาอาจาระและสมณสารูปอันงดงาม เพื่อสร้างความเลื่อมใสศรัทธาแก่พุทธศาสนิกชนและชาวต่างประเทศ</p>', '/images/news1.jpg'),

(2, 'ประกาศ', '๑๐ กรกฎาคม ๒๕๖๙', 'แจ้งเปิดระบบยื่นคำร้องเดินทางไปต่างประเทศออนไลน์รูปแบบใหม่', 'สำนักงาน ศ.ต.ภ. เพิ่มช่องทางอำนวยความสะดวกในการยื่นและติดตามสถานะหนังสือเดินทางเล่มสีน้ำเงินผ่านระบบดิจิทัล', '<p>ศูนย์ควบคุมการไปต่างประเทศของพระภิกษุสามเณร (ศ.ต.ภ.) ร่วมกับสำนักงานพระพุทธศาสนาแห่งชาติ ได้พัฒนาและเปิดตัว <strong>"ระบบยื่นคำร้องขออนุมัติเดินทางไปต่างประเทศและติดตามสถานะออนไลน์ (e-Sotopo)"</strong> เพื่อยกระดับการให้บริการแก่พระสังฆาธิการและพระภิกษุสามเณรทั่วประเทศ</p><h4>จุดเด่นและบริการของระบบใหม่:</h4><ol><li><strong>ยื่นคำขอออนไลน์ตลอด ๒๔ ชั่วโมง:</strong> สามารถกรอกแบบฟอร์มขอความเห็นชอบและแนบเอกสารหนังสือสุทธิออนไลน์</li><li><strong>ระบบติดตามสถานะแบบเรียลไทม์ (Real-time Tracking):</strong> ตรวจสอบสถานะการดำเนินงาน ๔ ขั้นตอนผ่านรหัสติดตาม (Tracking Number) ได้ทันที</li><li><strong>ระบบฐานข้อมูลการอนุมัติแบบรวมศูนย์:</strong> ตรวจสอบประกาศรายชื่อและหนังสืออนุมัติได้อย่างโปร่งใส</li><li><strong>ลดขั้นตอนและระยะเวลา:</strong> ลดระยะเวลาการพิจารณาลงเหลือไม่เกิน ๑๕ วันทำการ</li></ol><p>พระภิกษุสามเณรและเจ้าอาวาสสามารถเริ่มเข้าใช้งานระบบผ่านหน้าเว็บไซต์หลักของ ศ.ต.ภ. ได้ตั้งแต่วันนี้เป็นต้นไป</p>', '/images/news2.jpg'),

(3, 'สาระน่ารู้', '๕ กรกฎาคม ๒๕๖๙', 'ขั้นตอนการขอหนังสือเดินทางเล่มสีน้ำเงิน (Official Passport)', 'ทำความเข้าใจความแตกต่างของหนังสือเดินทางราชการสำหรับพระภิกษุ เอกสารประกอบ และการยกเว้นค่าธรรมเนียมตามระเบียบกระทรวงการต่างประเทศ', '<p>หนังสือเดินทางเล่มสีน้ำเงิน หรือ <strong>หนังสือเดินทางราชการ (Official Passport)</strong> เป็นเอกสารสำคัญที่ออกให้แก่พระภิกษุสามเณรที่ได้รับอนุมัติจากมหาเถรสมาคมและศูนย์ ศ.ต.ภ. เพื่อเดินทางไปปฏิบัติศาสนกิจ เผยแผ่พระพุทธศาสนา หรือศึกษาต่อในต่างประเทศ</p><h4>เอกสารสำคัญที่ต้องเตรียม:</h4><ul><li>หนังสืออนุมัติจาก ศ.ต.ภ. หรือมติมหาเถรสมาคม (ฉบับจริงหรือสำเนารับรองถูกต้อง)</li><li>หนังสือสุทธิของพระภิกษุสามเณร (ตัวจริงพร้อมสำเนาทุกหน้าที่มีรายการบันทึก)</li><li>บัตรประจำตัวประชาชนไทย (ที่ยังไม่หมดอายุ)</li><li>สำเนาทะเบียนบ้านวัดต้นสังกัด</li><li>หนังสือเชิญหรือหนังสือตอบรับจากวัดหรือองค์กรศาสนาในต่างประเทศ</li></ul><h4>การยกเว้นค่าธรรมเนียม:</h4><p>พระภิกษุสามเณรที่เดินทางไปในนามคณะสงฆ์ไทยตามมติมหาเถรสมาคม จะได้รับการยกเว้นค่าธรรมเนียมหนังสือเดินทางราชการตามระเบียบกระทรวงการต่างประเทศ โดยสามารถยื่นขอทำหนังสือเดินทางได้ ณ กรมการกงสุล ถนนแจ้งวัฒนะ หรือสำนักงานหนังสือเดินทางชั่วคราวทั่วประเทศ</p>', '/images/news3.jpg'),

(4, 'การอบรม', '๑ กรกฎาคม ๒๕๖๙', 'โครงการอบรมพระธรรมทูตสายต่างประเทศ รุ่นที่ ๓๑ ประจำปี ๒๕๖๙', 'เปิดรับสมัครพระภิกษุเข้าอบรมเตรียมความพร้อมภาษาและกฎหมายระหว่างประเทศ ณ มหาวิทยาลัยมหาจุฬาลงกรณราชวิทยาลัย', '<p>มหาวิทยาลัยมหาจุฬาลงกรณราชวิทยาลัย ร่วมกับศูนย์ ศ.ต.ภ. และสมัชชาสงฆ์ไทยในต่างแดน เปิดรับสมัครพระภิกษุผู้มีศรัทธาและคุณสมบัติครบถ้วน เข้ารับการอบรมในโครงการพระธรรมทูตสายต่างประเทศ รุ่นที่ ๓๑ เพื่อเตรียมความพร้อมสู่การเผยแผ่พระพุทธศาสนาในระดับสากล</p><h4>เนื้อหาหลักสูตรการอบรม:</h4><ul><li><strong>ทักษะภาษาและการสื่อสารสากล:</strong> ภาษาอังกฤษและภาษาท้องถิ่นสำหรับการแสดงธรรมและการสนทนาธรรม</li><li><strong>กฎหมายและระเบียบสากล:</strong> กฎหมายคนเข้าเมือง วีซ่า และสิทธิมนุษยชนในต่างแดน</li><li><strong>การบริหารจัดการวัดไทย:</strong> การดูแลศาสนสมบัติ การเงิน และการจัดกิจกรรมเพื่อชุมชนไทย</li><li><strong>การสอนสมาธิภาวนาแก่ชาวต่างชาติ:</strong> จิตวิทยาและการปรับตัวข้ามวัฒนธรรม</li></ul><p>กำหนดการรับสมัครตั้งแต่บัดนี้ถึงวันที่ ๒๕ กรกฎาคม ๒๕๖๙ และเริ่มอบรมระหว่างวันที่ ๑ สิงหาคม – ๓๐ ตุลาคม ๒๕๖๙ ณ สถาบันพระธรรมทูต มจร วังน้อย จังหวัดพระนครศรีอยุธยา</p>', '/images/news1.jpg'),

(5, 'ระเบียบ ศ.ต.ภ.', '๒๕ มิถุนายน ๒๕๖๙', 'ข้อปฏิบัติตนของพระธรรมทูตในการจำพรรษา ณ วัดไทยในต่างประเทศ', 'เน้นย้ำระเบียบมหาเถรสมาคมว่าด้วยการส่งพระภิกษุไปต่างประเทศ พ.ศ. ๒๕๓๗ และฉบับแก้ไขเพิ่มเติมเพื่อความเรียบร้อยของพุทธศาสนกิจ', '<p>สำนักงาน ศ.ต.ภ. ขอแจ้งเน้นย้ำแนวทางปฏิบัติสำหรับพระธรรมทูตและพระภิกษุสงฆ์ที่เดินทางไปปฏิบัติศาสนกิจและจำพรรษา ณ วัดไทยในต่างประเทศ เพื่อรักษาความเป็นระเบียบเรียบร้อยและความสง่างามแห่งคณะสงฆ์ไทย</p><h4>แนวทางปฏิบัติ ๕ ประการ:</h4><ol><li><strong>การรายงานตัว:</strong> เมื่อเดินทางถึงประเทศปลายทาง ให้รายงานตัวต่อหัวหน้าสายพระธรรมทูตหรือประธานสมัชชาสงฆ์ไทยในพื้นที่โดยทันที</li><li><strong>การพำนัก:</strong> พำนัก ณ เสนาสนะหรือวัดที่ระบุไว้ในใบคำร้องอย่างถูกต้อง ไม่ออกไปพำนักในสถานที่อันมิบังควรหรือย่านอโคจร</li><li><strong>การบำเพ็ญสมณธรรม:</strong> ปฏิบัติศาสนกิจ ทำวัตรสวดมนต์ และอบรมสั่งสอนธรรมะแก่สาธุชนอย่างสม่ำเสมอ</li><li><strong>การปฏิบัติตามกฎหมาย:</strong> เคารพและปฏิบัติตามกฎหมาย ระเบียบ และจารีตประเพณีของประเทศเจ้าบ้านอย่างเคร่งครัด</li><li><strong>การต่ออายุหนังสืออนุมัติ:</strong> ในกรณีมีความจำเป็นต้องอยู่ปฏิบัติศาสนกิจต่อเนื่อง ให้ยื่นเรื่องขอต่ออายุล่วงหน้าไม่น้อยกว่า ๓๐ วันก่อนเอกสารเดิมหมดอายุ</li></ol>', '/images/news2.jpg'),

(6, 'มติมส.', '๑๕ มิถุนายน ๒๕๖๙', 'มติมหาเถรสมาคม ครั้งที่ ๑๔/๒๕๖๔ ว่าด้วยการปรับปรุงระเบียบหนังสือเดินทางพระสงฆ์', 'ข้อกำหนดสำคัญในการพิจารณาคุณสมบัติและการยกเว้นค่าธรรมเนียมหนังสือเดินทางราชการสำหรับพระภิกษุสามเณร', '<p>ตามที่มหาเถรสมาคมได้มีมติครั้งที่ ๑๔/๒๕๖๔ กำหนดแนวทางปฏิบัติในการขอหนังสือเดินทางสำหรับพระภิกษุสามเณร โดยมีสาระสำคัญในการปรับปรุงขั้นตอนให้มีความรัดกุม โปร่งใส และอำนวยความสะดวกอย่างมีประสิทธิภาพ</p><h4>สาระสำคัญของมติ:</h4><ul><li><strong>คุณสมบัติของผู้ขอ:</strong> พระภิกษุต้องมีพรรษาพ้น ๕ พรรษา (มีนิสัยมุตตกะ) มีความประพฤติเรียบร้อยตามพระธรรมวินัย ได้รับความยินยอมจากเจ้าอาวาสและเจ้าคณะผู้ปกครองตามลำดับ</li><li><strong>การคัดกรองคุณสมบัติ:</strong> กำหนดให้มีการตรวจสอบประวัติทางพระวินัยและประวัติอาชญากรรมเพื่อความมั่นคงของพระศาสนา</li><li><strong>การคุ้มครองพระธรรมทูต:</strong> กำหนดมาตรการประสานงานร่วมกับกระทรวงการต่างประเทศในการดูแลคุ้มครองสิทธิและความปลอดภัยของพระสงฆ์ในต่างแดน</li></ul>', '/images/news3.jpg'),

(7, 'บริการ', '๑ มิถุนายน ๒๕๖๙', 'คู่มือการเตรียมเอกสารขอวีซ่าประเภท Religious Worker สำหรับสหรัฐอเมริกาและยุโรป', 'แนวทางการจัดเตรียมหนังสือเชิญจากวัด สัญญาการอุปถัมภ์ และหลักฐานการตรวจสอบประวัติเพื่อยื่นขอวีซ่าทางศาสนา', '<p>การเดินทางไปปฏิบัติศาสนกิจในสหรัฐอเมริกา (R-1 Religious Worker Visa) และกลุ่มประเทศเชงเก้น (Schengen Religious Visa) ต้องใช้เอกสารรับรองทางศาสนาที่ถูกต้องครบถ้วนตามกฎหมายตรวจคนเข้าเมืองของประเทศปลายทาง</p><h4>เอกสารประกอบที่จำเป็น:</h4><ul><li>หนังสือรับรองสถานะพระภิกษุสงฆ์จาก ศ.ต.ภ. ฉบับภาษาอังกฤษ (Official Endorsement Letter)</li><li>มติแต่งตั้งพระธรรมทูตจากมหาเถรสมาคม</li><li>หนังสือเชิญและเอกสารรับรองการอุปถัมภ์ (Sponsorship Certificate) จากวัดไทยที่จดทะเบียนถูกต้องตามกฎหมายในต่างแดน</li><li>แผนการปฏิบัติงานศาสนกิจ (Itinerary / Ministry Plan) ระบุภารกิจและระยะเวลาอย่างชัดเจน</li></ul><p>คำแนะนำ: ควรเริ่มดำเนินการขอเอกสารรับรองจาก ศ.ต.ภ. ล่วงหน้าอย่างน้อย ๖๐ วันก่อนกำหนดการเดินทางจริง</p>', '/images/news1.jpg'),

(8, 'ข่าวสาร', '๒๐ พฤษภาคม ๒๕๖๙', 'พิธีเปิดศูนย์ประสานงานพระธรรมทูตและอำนวยความสะดวกหนังสือเดินทาง วัดประยุรวงศาวาส', 'เพิ่มศูนย์บริการครบวงจร (One-Stop Service) ฝั่งธนบุรี เพื่ออำนวยความสะดวกในการตรวจเอกสารและให้คำปรึกษา', '<p>เพื่อลดความแออัดและเพิ่มความสะดวกแก่พระภิกษุสามเณรในเขตกรุงเทพฯ ฝั่งธนบุรีและปริมณฑล ศ.ต.ภ. ได้เปิด <strong>"ศูนย์อำนวยความสะดวกหนังสือเดินทางและข้อมูลพระธรรมทูต"</strong> ณ วัดประยุรวงศาวาสวรวิหาร เขตธนบุรี กรุงเทพมหานคร</p><h4>การให้บริการของศูนย์:</h4><ul><li>บริการตรวจสอบความถูกต้องของเอกสารคำร้องก่อนเสนอคณะกรรมการ</li><li>ให้คำปรึกษาขั้นตอนการขอวีซ่าและหนังสือเดินทางราชการทุกประเภท</li><li>บริการถ่ายภาพติดบัตรตามมาตรฐานสากลของกรมการกงสุล</li><li>จุดรับส่งเอกสารคำร้องและประสานงานด่วนกับสำนักงานส่วนกลาง วัดสระเกศ</li></ul><p>ศูนย์เปิดให้บริการทุกวันจันทร์ - เสาร์ เวลา ๐๙.๐๐ - ๑๖.๐๐ น. (เว้นวันหยุดนักขัตฤกษ์) โทรศัพท์ 02-465-5592</p>', '/images/news2.jpg');

-- Seeding committees using local images in /images
INSERT INTO `committees` (`id`, `name`, `role`, `description`, `image_url`, `level`) VALUES
(1, 'พระพรหมบัณฑิต (ประยูร ธมฺมจิตฺโต)', 'ประธานคณะกรรมการ ศ.ต.ภ.', 'กรรมการมหาเถรสมาคม, เจ้าอาวาสวัดประยุรวงศาวาสวรวิหาร, ประธานสภาสากลวันวิสาขบูชาโลก', '/images/comm1.jpg', 1),
(2, 'พระธรรมโพธิวงศ์ (วีรยุทธ์ วีรยุทฺโธ)', 'รองประธานคณะกรรมการ', 'เจ้าอาวาสวัดไทยพุทธคยา หัวหน้าพระธรรมทูตสายประเทศอินเดีย-เนปาล', '/images/comm2.jpg', 2),
(3, 'พระเทพพุทธิวิเทศ (สถิตย์ ฐิตธมฺโม)', 'รองประธานคณะกรรมการ', 'เจ้าอาวาสวัดพุทธาวาส ประธานสมัชชาสงฆ์ไทยในสหรัฐอเมริกา', '/images/comm3.jpg', 2),
(4, 'พระครูปลัดสุวัฒนบัณฑิตคุณ', 'กรรมการและเลขานุการ ศ.ต.ภ.', 'รองเจ้าอาวาสวัดประยุรวงศาวาสวรวิหาร ผู้ช่วยผู้จัดการศูนย์อำนวยความสะดวก', '/images/comm4.jpg', 3),
(5, 'พระศรีวชิรวาที (ปริญญา ปริญญาโณ)', 'กรรมการ', 'เลขานุการเจ้าคณะภาค ๑๔ วัดสุวรรณารามราชวรวิหาร', '/images/comm5.jpg', 3),
(6, 'ผู้แทนสำนักงานพระพุทธศาสนาแห่งชาติ', 'กรรมการฝ่ายบริหาร', 'ผู้อำนวยการกองพุทธจักรและพุทธศาสนสถาน', '/images/comm6.jpg', 3);

-- Seeding announcements
INSERT INTO `announcements` (`id`, `announcement_number`, `topic`, `approve_date`) VALUES
(1, 'พศ ๐๐๐๘/๒๕๖๙', 'อนุมัติพระภิกษุเดินทางไปปฏิบัติศาสนกิจ ณ สหรัฐอเมริกา', '๑๒ กรกฎาคม ๒๕๖๙'),
(2, 'พศ ๐๐๐๙/๒๕๖๙', 'อนุมัติพระภิกษุเดินทางไปปฏิบัติศาสนกิจ ณ ประเทศอินเดียและเนปาล', '๑๑ กรกฎาคม ๒๕๖๙'),
(3, 'พศ ๐๐๑๐/๒๕๖๙', 'อนุมัติพระภิกษุเดินทางไปปฏิบัติศาสนกิจ ณ ประเทศสิงคโปร์และมาเลเซีย', '๑० กรกฎาคม ๒๕๖๙'),
(4, 'พศ ๐๐๑๑/๒๕๖๙', 'อนุมัติพระภิกษุเดินทางไปปฏิบัติศาสนกิจ ณ สหราชอาณาจักร', '๐๙ กรกฎาคม ๒๕๖๙'),
(5, 'พศ ๐๐๑๒/๒๕๖๙', 'อนุมัติพระภิกษุเดินทางไปปฏิบัติศาสนกิจ ณ ประเทศออสเตรเลีย', '๐๘ กรกฎาคม ๒๕๖๙'),
(6, 'พศ ๐๐๑๓/๒๕๖๙', 'อนุมัติพระภิกษุเดินทางไปปฏิบัติศาสนกิจ ณ ประเทศญี่ปุ่น', '๐๗ กรกฎาคม ๒๕๖๙'),
(7, 'พศ ๐๐๑๔/๒๕๖๙', 'อนุมัติพระภิกษุเดินทางไปปฏิบัติศาสนกิจ ณ ประเทศเยอรมนี', '๐๖ กรกฎาคม ๒๕๖๙'),
(8, 'พศ ๐๐๑๕/๒๕๖๙', 'อนุมัติพระภิกษุเดินทางไปปฏิบัติศาสนกิจ ณ ประเทศฝรั่งเศสและนอร์เวย์', '๐๕ กรกฎาคม ๒๕๖๙'),
(9, 'พศ ๐๐๑๖/๒๕๖๙', 'อนุมัติพระภิกษุเดินทางไปปฏิบัติศาสนกิจ ณ ประเทศนิวซีแลนด์', '๐๔ กรกฎาคม ๒๕๖๙');

